// Extracts an intermediate representation (IR) of the Autumn API from the
// published `autumn-js` bundle (dist/sdk/index.js + dist/sdk/index.d.ts).
//
// The JS SDK is generated by Speakeasy and describes every request/response
// shape with zod schemas. We statically walk those schema expressions with
// acorn (nothing from the package is executed) and pull doc comments from the
// TypeScript declarations.
//
// Usage: node extract.mjs <path/to/autumn-js/package> <out.json>

import * as acorn from "acorn";
import ts from "typescript";
import fs from "node:fs";
import path from "node:path";

const [pkgDir, outFile] = process.argv.slice(2);
if (!pkgDir || !outFile) {
  console.error("usage: node extract.mjs <autumn-js package dir> <out.json>");
  process.exit(1);
}

const pkgJson = JSON.parse(fs.readFileSync(path.join(pkgDir, "package.json"), "utf8"));
const jsSrc = fs.readFileSync(path.join(pkgDir, "dist/sdk/index.js"), "utf8");
const dtsSrc = fs.readFileSync(path.join(pkgDir, "dist/sdk/index.d.ts"), "utf8");

const comments = [];
const ast = acorn.parse(jsSrc, {
  ecmaVersion: "latest",
  sourceType: "script",
  onComment: comments,
});

// ---------------------------------------------------------------------------
// Top-level declarations
// ---------------------------------------------------------------------------

const vars = new Map(); // name -> init node
const funcs = new Map(); // name -> FunctionDeclaration
for (const st of ast.body) {
  if (st.type === "VariableDeclaration") {
    for (const d of st.declarations) if (d.id.type === "Identifier" && d.init) vars.set(d.id.name, d.init);
  } else if (st.type === "FunctionDeclaration") {
    funcs.set(st.id.name, st);
  }
}

const Z = "z46__namespace";
function zfn(node) {
  // Returns the zod function name for `z46__namespace.<fn>(...)`, the helper
  // name for `helper(...)`, or null.
  if (node.type !== "CallExpression") return null;
  const c = node.callee;
  if (c.type === "MemberExpression" && c.object.type === "Identifier" && c.object.name === Z) return "z." + c.property.name;
  if (c.type === "Identifier") return c.name;
  return null;
}

function literalValue(node) {
  if (node.type === "Literal") return node.value;
  if (node.type === "UnaryExpression" && node.operator === "-" && node.argument.type === "Literal") return -node.argument.value;
  if (node.type === "Identifier" && node.name === "undefined") return undefined;
  throw new Error("not a literal: " + jsSrc.slice(node.start, node.end));
}

function objectLiteral(node) {
  const out = {};
  for (const p of node.properties) {
    const key = p.key.type === "Identifier" ? p.key.name : p.key.value;
    out[key] = p.value;
  }
  return out;
}

// Enum objects: `var Foo = { A: "a", B: "b" };`
const enumObjects = new Map();
for (const [name, init] of vars) {
  if (init.type !== "ObjectExpression" || init.properties.length === 0) continue;
  const values = [];
  let ok = true;
  for (const p of init.properties) {
    if (p.type !== "Property" || p.value.type !== "Literal" || (typeof p.value.value !== "string" && typeof p.value.value !== "number")) {
      ok = false;
      break;
    }
    values.push({ key: p.key.type === "Identifier" ? p.key.name : String(p.key.value), value: p.value.value });
  }
  if (ok) enumObjects.set(name, values);
}

// ---------------------------------------------------------------------------
// Schema expression -> IR
// ---------------------------------------------------------------------------

const SCHEMA_RE = /^(.*)\$(inbound|outbound)Schema$/;
const usedEnums = new Map(); // enum name -> {values, open}

function remapFromTransform(fnNode) {
  // transform((v) => remap(v, {...})) or transform((v) => ({...remap(v, {...})}))
  let found = null;
  (function walk(n) {
    if (!n || typeof n !== "object" || found) return;
    if (n.type === "CallExpression" && n.callee.type === "Identifier" && n.callee.name === "remap") {
      found = {};
      for (const p of n.arguments[1].properties) {
        const k = p.key.type === "Identifier" ? p.key.name : p.key.value;
        found[k] = p.value.value; // may be null (drop)
      }
      return;
    }
    for (const k in n) if (k !== "type" && typeof n[k] === "object") walk(n[k]);
  })(fnNode);
  return found;
}

function conv(node) {
  // Identifier reference to another schema
  if (node.type === "Identifier") {
    const m = SCHEMA_RE.exec(node.name);
    if (m) return { kind: "ref", name: m[1], dir: m[2] };
    throw new Error("unknown identifier " + node.name);
  }
  const fn = zfn(node);
  const args = node.arguments || [];
  switch (fn) {
    case "z.string":
    case "string5":
      return { kind: "string" };
    case "z.number":
    case "number2":
      return { kind: "number" };
    case "z.int":
      return { kind: "int" };
    case "z.boolean":
    case "boolean2":
      return { kind: "boolean" };
    case "z.any":
    case "z.unknown":
      return { kind: "any" };
    case "z.null":
      return { kind: "null" };
    case "date2":
    case "z.iso.datetime":
      return { kind: "string" };
    case "bigint":
      return { kind: "int" };
    case "z.literal":
      return { kind: "literal", value: literalValue(args[0]) };
    case "literal3":
      return { kind: "literal", value: literalValue(args[0]), lenient: true };
    case "z.optional":
      return { kind: "optional", inner: conv(args[0]) };
    case "optional3":
      return { kind: "optional", inner: conv(args[0]), lenient: true };
    case "z.nullable":
    case "nullable":
      return { kind: "nullable", inner: conv(args[0]) };
    case "z._default":
      return { kind: "default", inner: conv(args[0]), value: literalValue(args[1]) };
    case "z.array":
      return { kind: "array", inner: conv(args[0]) };
    case "z.record":
      return { kind: "record", key: conv(args[0]), value: conv(args[1]) };
    case "z.lazy": {
      const body = args[0].body;
      return conv(body);
    }
    case "z.enum": {
      const a = args[0];
      if (a.type === "Identifier" && enumObjects.has(a.name)) {
        noteEnum(a.name, false);
        return { kind: "enum", name: a.name };
      }
      if (a.type === "ArrayExpression") return { kind: "inlineEnum", values: a.elements.map(literalValue) };
      throw new Error("bad z.enum");
    }
    case "inboundSchema": {
      const a = args[0];
      noteEnum(a.name, true);
      return { kind: "enum", name: a.name };
    }
    case "smartUnion":
    case "z.union":
      return { kind: "union", options: args[0].elements.map(conv) };
    case "discriminatedUnion": {
      const prop = literalValue(args[0]);
      const opts = objectLiteral(args[1]);
      return {
        kind: "taggedUnion",
        prop,
        options: Object.entries(opts).map(([tag, n]) => ({ tag, type: conv(n) })),
      };
    }
    case "z.object":
      return objectNode(args[0], false);
    case "z.catchall": {
      const o = conv(args[0]);
      o.catchall = true;
      return o;
    }
    case "z.pipe": {
      const [a, b] = args;
      const inner = conv(a);
      const remap = zfn(b) === "z.transform" ? remapFromTransform(b) : null;
      if (inner.kind === "object") {
        inner.remap = remap || {};
        return inner;
      }
      return inner;
    }
    default:
      throw new Error("unsupported schema call " + fn + " :: " + jsSrc.slice(node.start, Math.min(node.end, node.start + 200)));
  }
}

function noteEnum(name, open) {
  const cur = usedEnums.get(name);
  if (cur) cur.open = cur.open || open;
  else usedEnums.set(name, { values: enumObjects.get(name), open });
}

function objectNode(objExpr, catchall) {
  const fields = [];
  for (const p of objExpr.properties) {
    const key = p.key.type === "Identifier" ? p.key.name : p.key.value;
    fields.push({ key, type: conv(p.value) });
  }
  return { kind: "object", fields, catchall, remap: {} };
}

const schemas = {}; // name -> { inbound?: IR, outbound?: IR }
for (const [varName, init] of vars) {
  const m = SCHEMA_RE.exec(varName);
  if (!m) continue;
  const [, name, dir] = m;
  let ir;
  try {
    ir = conv(init);
  } catch (e) {
    console.error(`failed on ${varName}: ${e.message}`);
    process.exit(1);
  }
  (schemas[name] ??= {})[dir] = ir;
}

// ---------------------------------------------------------------------------
// Operations
// ---------------------------------------------------------------------------

function findAll(node, pred, out = []) {
  if (!node || typeof node !== "object") return out;
  if (Array.isArray(node)) {
    for (const n of node) findAll(n, pred, out);
    return out;
  }
  if (pred(node)) out.push(node);
  for (const k in node) if (k !== "type" && typeof node[k] === "object") findAll(node[k], pred, out);
  return out;
}

function operationFromFunc(funcName) {
  // funcName(client, request, options) { return new APIPromise($doN(...)) }
  const f = funcs.get(funcName);
  const doCall = findAll(f.body, (n) => n.type === "CallExpression" && n.callee.type === "Identifier" && /^\$do\d*$/.test(n.callee.name))[0];
  const d = funcs.get(doCall.callee.name);
  const op = { func: funcName };
  const parseCalls = findAll(d.body, (n) => zfn(n) === "z.parse");
  if (parseCalls.length) op.request = conv(parseCalls[0].arguments[0]);
  op.sendsBody = findAll(d.body, (n) => n.type === "CallExpression" && n.callee.type === "Identifier" && n.callee.name === "encodeJSON").length > 0;
  const pathCall = findAll(d.body, (n) => n.type === "CallExpression" && n.callee.type === "Identifier" && n.callee.name === "pathToFunc")[0];
  op.path = pathCall.arguments[0].value;
  for (const p of findAll(d.body, (n) => n.type === "Property" && n.key.type === "Identifier")) {
    if (p.key.name === "operationID") op.operationId = p.value.value;
    if (p.key.name === "method" && p.value.type === "Literal") op.method = p.value.value;
  }
  op.responses = findAll(d.body, (n) => n.type === "CallExpression" && n.callee.type === "Identifier" && n.callee.name === "json").map((c) => ({
    status: c.arguments[0].value,
    type: conv(c.arguments[1]),
  }));
  const retry = findAll(d.body, (n) => n.type === "Property" && n.key.type === "Identifier" && n.key.name === "retryCodes")[0];
  if (retry) {
    const arr = findAll(retry.value, (n) => n.type === "ArrayExpression")[0];
    op.retryCodes = arr.elements.map((e) => e.value);
  }
  return op;
}

function jsdocBefore(pos) {
  // Closest block comment ending right before `pos` (only whitespace between).
  let best = null;
  for (const c of comments) {
    if (c.type !== "Block" || c.end > pos) continue;
    if (/^\s*$/.test(jsSrc.slice(c.end, pos))) best = c;
  }
  if (!best || !best.value.startsWith("*")) return null;
  return best.value
    .split("\n")
    .map((l) => l.replace(/^\s*\*\s?/, ""))
    .join("\n")
    .replace(/^\*\s*/, "")
    .trim();
}

const classes = {}; // className -> { methods: [...], getters: [...] }
for (const [name, init] of vars) {
  if (init.type !== "ClassExpression") continue;
  if (!init.superClass || init.superClass.type !== "Identifier" || init.superClass.name !== "ClientSDK") continue;
  const cls = { methods: [], resources: [] };
  for (const m of init.body.body) {
    if (m.type !== "MethodDefinition" || m.key.type !== "Identifier") continue;
    if (m.kind === "get") {
      const n = findAll(m.value.body, (x) => x.type === "NewExpression")[0];
      if (n && n.callee.type === "Identifier") cls.resources.push({ name: m.key.name, className: n.callee.name, doc: jsdocBefore(m.start) });
      continue;
    }
    if (m.kind !== "method" || m.key.name === "constructor") continue;
    const call = findAll(m.value.body, (x) => x.type === "CallExpression" && x.callee.type === "Identifier" && funcs.has(x.callee.name) && x.callee.name !== "unwrapAsync")[0];
    if (!call) continue;
    cls.methods.push({ name: m.key.name, doc: jsdocBefore(m.start), ...operationFromFunc(call.callee.name) });
  }
  classes[name] = cls;
}

// ---------------------------------------------------------------------------
// Docs from the .d.ts
// ---------------------------------------------------------------------------

const sf = ts.createSourceFile("index.d.ts", dtsSrc, ts.ScriptTarget.Latest, true);
const typeDocs = {}; // TypeName -> { doc, fields: {camelName: doc} }
const enumDocs = {}; // EnumName -> { doc, values: {key: doc} }

function jsDocText(node) {
  const docs = ts.getJSDocCommentsAndTags(node).filter((d) => d.kind === ts.SyntaxKind.JSDoc);
  if (!docs.length) return null;
  const d = docs[docs.length - 1];
  let text = typeof d.comment === "string" ? d.comment : d.comment ? d.comment.map((c) => c.text).join("") : "";
  for (const tag of d.tags ?? []) {
    const tc = typeof tag.comment === "string" ? tag.comment : tag.comment ? tag.comment.map((c) => c.text).join("") : "";
    if (tag.tagName.text === "deprecated") text += `\n\n@deprecated ${tc}`.trimEnd();
  }
  return text.trim() || null;
}

function collectMembers(typeNode, into) {
  if (!typeNode) return;
  if (ts.isTypeLiteralNode(typeNode)) {
    for (const mem of typeNode.members) {
      if (ts.isPropertySignature(mem) && mem.name) {
        const n = mem.name.text ?? mem.name.getText();
        const doc = jsDocText(mem);
        if (doc && !(n in into)) into[n] = doc;
      }
    }
  } else if (ts.isIntersectionTypeNode(typeNode)) {
    for (const t of typeNode.types) collectMembers(t, into);
  }
}

ts.forEachChild(sf, (node) => {
  if (ts.isTypeAliasDeclaration(node)) {
    const name = node.name.text;
    if (name.endsWith("$Outbound")) return;
    const fields = {};
    collectMembers(node.type, fields);
    typeDocs[name] = { doc: jsDocText(node), fields };
  } else if (ts.isVariableStatement(node)) {
    for (const decl of node.declarationList.declarations) {
      const name = decl.name.getText();
      if (!enumObjects.has(name) || !decl.type || !ts.isTypeLiteralNode(decl.type)) continue;
      const values = {};
      for (const mem of decl.type.members) {
        const doc = jsDocText(mem);
        if (doc && mem.name) values[mem.name.getText().replace(/^["']|["']$/g, "")] = doc;
      }
      enumDocs[name] = { doc: jsDocText(node), values };
    }
  }
});

const enums = {};
for (const [name, { values, open }] of usedEnums) enums[name] = { values, open, docs: enumDocs[name] ?? null };

fs.writeFileSync(
  outFile,
  JSON.stringify(
    {
      source: { package: pkgJson.name, version: pkgJson.version },
      sdkMetadata: (() => {
        const init = vars.get("SDK_METADATA");
        return init ? Object.fromEntries(Object.entries(objectLiteral(init)).map(([k, v]) => [k, v.value])) : null;
      })(),
      schemas,
      enums,
      classes,
      typeDocs,
    },
    null,
    1,
  ),
);
console.log(
  `extracted ${Object.keys(schemas).length} schemas, ${Object.keys(enums).length} enums, ` +
    `${Object.values(classes).reduce((a, c) => a + c.methods.length, 0)} operations from ${pkgJson.name}@${pkgJson.version}`,
);
